INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`,
  `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`,
  `BoxBroadcastTextID`, `VerifiedBuild`) VALUES
(9950200, 0, 0, '我对你没有恶意。我听说你可能还记得以前的生活。', 0, 1, 1, 9950201, 0, 0, 0, '', 0, 0),
(9950201, 0, 0, '拜托，试着想起来，你曾经是个人类，对吧？你叫什么名字？', 0, 1, 1, 9950202, 0, 0, 0, '', 0, 0),
(9950202, 0, 0, '朱莉，嗯？这可能是这里我能问出的最多信息了。', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(9950207, 0, 1, '我想看看你的货物。', 0, 3, 128, 0, 0, 0, 0, '', 0, 0);

