-- The Reunited talk after 'Addle's Stead' is turned in to Julie Addle, line by line as recorded, with Captain Aldric
-- Vayne's line (jLBZUj7KUhw 1:51:53), and Ryton Altham's lines about his pumpkins (jLBZUj7KUhw 1:53:17 and 1:53:29).
DELETE FROM `creature_text` WHERE `CreatureID` IN (764561, 254906, 764560, 255157);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`,
  `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(764561, 0, 0, '朱……莉？', 12, 0, 100, 0, 0, 0, 0, 0, '夜祸狼人 - 愿我们重逢 0'),
(764561, 1, 0, '朱莉，快走开！我打不过它！', 12, 0, 100, 0, 0, 0, 0, 0, '夜祸狼人 - 愿我们重逢 1'),
(764561, 2, 0, '你不明白，不只是我！狼人教派，他们在追寻狼人的源头！他们称它为镰刀……', 12, 0, 100, 0, 0, 0, 0, 0, '夜祸狼人 - 愿我们重逢 2'),
(764561, 3, 0, '不！我的头脑清醒了，但我还能感觉到它在慢慢回来，你不能放我出去！我留在这里对你更安全！对所有人都更安全！', 12, 0, 100, 0, 0, 0, 0, 0, '夜祸狼人 - 愿我们重逢 3'),
(764561, 4, 0, '把我变成这样的人是一个叫杰维斯的狼人，告诉守夜人找到他！', 12, 0, 100, 0, 0, 0, 0, 0, '夜祸狼人 - 愿我们重逢 4'),
(254906, 0, 0, '阿尔维斯？你真的认出我了！我就知道你还在这里！', 12, 0, 100, 0, 0, 0, 0, 0, '朱莉·阿德尔 - 愿我们重逢 0'),
(254906, 1, 0, '别担心我！只要试着想起来，你的名字是阿尔维斯·阿德尔……', 12, 0, 100, 0, 0, 0, 0, 0, '朱莉·阿德尔 - 愿我们重逢 1'),
(254906, 2, 0, '那些都不重要了！我们得找到办法把你变回来！不，只要你能保持自我，形态改变也没关系，我会告诉守夜人放你出来！', 12, 0, 100, 0, 0, 0, 0, 0, '朱莉·阿德尔 - 愿我们重逢 2'),
(254906, 3, 0, '我会告诉他们！只是……再坚持一会儿，好吗？', 12, 0, 100, 0, 0, 0, 0, 0, '朱莉·阿德尔 - 愿我们重逢 3'),
(764560, 0, 0, '一切看起来都井井有条！', 12, 0, 100, 0, 0, 0, 0, 0, '奥德里克·维恩队长 - 愿我们重逢 0'),
(255157, 0, 0, '我的南瓜到底怎么了？！', 12, 0, 100, 0, 0, 0, 0, 0, '莱顿·阿尔瑟姆 - 环境对话 0'),
(255157, 1, 0, '这就是我用迪菲亚的魔法的下场……', 12, 0, 100, 0, 0, 0, 0, 0, '莱顿·阿尔瑟姆 - 环境对话 1');

